import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

interface FineRule {
    long fine(long daysLate);
}

class BookFine implements FineRule {
    public long fine(long daysLate) {
        return Math.max(0, daysLate) * 500;
    }
}

class JournalFine implements FineRule {
    public long fine(long daysLate) {
        return Math.max(0, daysLate) * 300;
    }
}

// Tambahkan dua kelas aturan baru yang mengimplementasikan FineRule, tanpa mengubah kelas lain: DigitalFine (selalu 0) dan ThesisFine (Rp1000 per hari, hari yang dihitung paling banyak 20).

class FineService {
    private Map<String, FineRule> rules = new HashMap<>();

    void register(String type, FineRule rule) {
        rules.put(type, rule);
    }

    long calculate(String type, long daysLate) {
        FineRule rule = rules.get(type);
        if (rule == null) {
            throw new IllegalArgumentException("Jenis tidak dikenal: " + type);
        }
        return rule.fine(daysLate);
    }
}

public class Main {
    public static void main(String[] args) {
        FineService service = new FineService();
        service.register("buku", new BookFine());
        service.register("jurnal", new JournalFine());
        // Daftarkan aturan baru dengan nama jenis "digital" dan "skripsi".
        Scanner in = new Scanner(System.in);
        while (in.hasNextLine()) {
            String line = in.nextLine().trim();
            if (line.equals("selesai")) {
                break;
            }
            String[] p = line.split(" ");
            try {
                System.out.println(p[0] + ": Rp" + service.calculate(p[0], Long.parseLong(p[1])));
            } catch (IllegalArgumentException e) {
                System.out.println(e.getMessage());
            }
        }
    }
}
